contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 loanID_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanID_ > 0 && loanID_ >= type(uint256).max - 1);

        bool reverted;
        c.provideNewTermsForRoll(loanID_, interest_, loanToCollateral_, duration_); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted);
    }

    receive() external payable {}
}

