pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 loanID_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) internal {
        vm.assume(loanID_ > 0 && loanID_ >= type(uint256).max - 1);
        bool reverted;
        try c.provideNewTermsForRoll(loanID_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 loanID_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        _run(loanID_, interest_, loanToCollateral_, duration_);
    }

    receive() external payable {}
}
